function ringSums(code: number[], k: number): number[] {
  const n = code.length;
  return code.map((_, i) => {
    let s = 0;
    for (let d = 1; d <= Math.abs(k); d++) s += code[(i + (k > 0 ? d : -d) + n) % n];
    return s;
  });
}

