class Solution:
    def ringSums(self, code: List[int], k: int) -> List[int]:
        n = len(code)
        step = 1 if k > 0 else -1
        return [sum(code[(i + step * d) % n] for d in range(1, abs(k) + 1)) for i in range(n)]

