function ringSums(code: number[], k: number): number[] {
  const n = code.length;
  const out = new Array(n).fill(0);
  if (k === 0) return out;
  let start = k > 0 ? 1 : n + k;
  let end = k > 0 ? k : n - 1;
  let sum = 0;
  for (let i = start; i <= end; i++) sum += code[i % n];
  for (let i = 0; i < n; i++) {
    out[i] = sum;
    sum -= code[start % n];
    end++;
    sum += code[end % n];
    start++;
  }
  return out;
}

